import{_ as t,o as e,c as i,ag as n}from"./chunks/framework.CrXGS008.js";const z=JSON.parse('{"title":"Panel /nay","description":"","frontmatter":{},"headers":[],"relativePath":"pl/nay-lib/panel.md","filePath":"pl/nay-lib/panel.md"}'),o={name:"pl/nay-lib/panel.md"};function d(r,a,s,c,l,p){return e(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="panel-nay" tabindex="-1">Panel /nay <a class="header-anchor" href="#panel-nay" aria-label="Permalink to &quot;Panel /nay&quot;">​</a></h1><p>Wpisz <code>/nay</code> w grze, aby otworzyć panel ustawień. Widzisz w nim każdy skrypt Nayretis, który możesz konfigurować. Gracze z <code>nay.admin</code> widzą też sekcję <strong>Serwer</strong>: stronę Nayretis, Uprawnienia, API, Webhooki i Dziennik.</p><p>Ustawienia są zapisywane w bazie danych. Po naciśnięciu <strong>Zapisz</strong> nowa wartość jest sprawdzana, zapisywana, odnotowywana w <a href="/pl/nay-lib/audit">dzienniku zmian</a> i od razu stosowana u wszystkich połączonych graczy. Restart nie jest potrzebny.</p><p>Niektóre strony skryptów mają też przyciski akcji, na przykład <strong>Zarządzaj tunelami</strong> na stronie Car Wash.</p><h2 id="ustawienia-nayretis" tabindex="-1">Ustawienia Nayretis <a class="header-anchor" href="#ustawienia-nayretis" aria-label="Permalink to &quot;Ustawienia Nayretis&quot;">​</a></h2><p>Strona <strong>Nayretis</strong> zawiera ustawienia wspólne dla wszystkich skryptów.</p><p>Kolumna <strong>W /nay</strong> to nazwa wyświetlana w panelu. Klucz to nazwa używana przez <code>config.lua</code> i <a href="/pl/nay-lib/api">API HTTP</a>.</p><table tabindex="0"><thead><tr><th>W /nay</th><th>Klucz</th><th>Typ</th><th>Domyślnie</th><th>Opis</th></tr></thead><tbody><tr><td>Język</td><td><code>Locale</code></td><td>język</td><td>angielski lub wartość <code>nay:locale</code></td><td>Język wszystkich skryptów Nayretis: angielski, francuski, hiszpański, portugalski, polski lub niemiecki.</td></tr><tr><td>Motyw interfejsu</td><td><code>Theme</code></td><td><code>graphite</code> lub <code>papier</code></td><td><code>graphite</code></td><td>Wygląd interfejsów Nayretis: ciemny (Graphite) lub jasny (Papier).</td></tr><tr><td>API HTTP</td><td><code>ApiEnabled</code></td><td>wł. / wył.</td><td>wył.</td><td>Włącza <a href="/pl/nay-lib/api">API HTTP</a>. Dopóki jest wyłączone, każda trasa odpowiada <code>503 api_disabled</code>.</td></tr><tr><td>Maksymalny rozmiar żądania (KB)</td><td><code>ApiMaxBodyKb</code></td><td>liczba od 1 do 10240</td><td>1024</td><td>Największa treść żądania akceptowana przez API, w KB.</td></tr><tr><td>Przechowywanie dziennika (dni)</td><td><code>AuditRetentionDays</code></td><td>liczba od 0 do 3650</td><td>90</td><td>Wpisy dziennika zmian starsze niż ta liczba dni są usuwane codziennie. 0 zachowuje wszystko.</td></tr></tbody></table><h2 id="kto-moze-otworzyc-panel" tabindex="-1">Kto może otworzyć panel <a class="header-anchor" href="#kto-moze-otworzyc-panel" aria-label="Permalink to &quot;Kto może otworzyć panel&quot;">​</a></h2><ul><li><code>nay.admin</code> daje dostęp do wszystkiego.</li><li><code>nay.config</code> daje dostęp do ustawień wszystkich skryptów.</li><li><code>nay.audit</code> otwiera panel na dzienniku zmian.</li><li><code>&lt;resource&gt;.config</code> daje dostęp do ustawień jednego skryptu, na przykład <code>nay_car_wash.config</code>.</li></ul><p>Jak je nadać, opisuje strona <a href="/pl/nay-lib/permissions">Uprawnienia</a>.</p>',11)])])}const w=t(o,[["render",d]]);export{z as __pageData,w as default};
